import json


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def parse_book(text):
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        raise ValueError("book: invalid JSON")
    if not isinstance(data, dict):
        raise ValueError("book: expected an object")

    book_id = data.get("id")
    if not _is_int(book_id) or book_id < 1:
        raise ValueError("book.id: expected an integer of at least 1")

    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        raise ValueError("book.title: expected a non-empty string")

    year = data.get("year")
    if year is not None and not _is_int(year):
        raise ValueError("book.year: expected an integer or null")

    tags = data.get("tags", [])
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        raise ValueError("book.tags: expected a list of strings")

    price = data.get("price")
    if price is not None:
        if isinstance(price, bool) or not isinstance(price, (int, float)) or price < 0:
            raise ValueError("book.price: expected a number of at least 0")

    return {"id": book_id, "title": title.strip(), "year": year, "tags": tags, "price": price}


def to_canonical_json(book):
    return json.dumps(book, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

