def problem(text):
    try:
        parse_book(text)
    except ValueError as e:
        return str(e)
    return "accepted"

@test("a complete book")
def _():
    b = parse_book('{"id": 7, "title": "  Dune ", "year": 1965, "tags": ["sf"], "price": 9.5, "extra": true}')
    check_eq(b, {"id": 7, "title": "Dune", "year": 1965, "tags": ["sf"], "price": 9.5})

@test("optional fields")
def _():
    check_eq(parse_book('{"id": 1, "title": "A"}'), {"id": 1, "title": "A", "year": None, "tags": [], "price": None})
    check_eq(parse_book('{"id": 1, "title": "A", "year": null, "price": null, "tags": []}')["year"], None)
    check_eq(parse_book('{"id": 1, "title": "A", "price": 0}')["price"], 0)

@test("the document itself")
def _():
    check(problem('{"id": 1,').startswith("book: invalid JSON"))
    check(problem("[1, 2]").startswith("book: expected an object"))
    check(problem('"text"').startswith("book: expected an object"))

@test("each field")
def _():
    check(problem('{"title": "A"}').startswith("book.id"))
    check(problem('{"id": true, "title": "A"}').startswith("book.id"))
    check(problem('{"id": 0, "title": "A"}').startswith("book.id"))
    check(problem('{"id": "7", "title": "A"}').startswith("book.id"))
    check(problem('{"id": 1}').startswith("book.title"))
    check(problem('{"id": 1, "title": "   "}').startswith("book.title"))
    check(problem('{"id": 1, "title": 5}').startswith("book.title"))
    check(problem('{"id": 1, "title": "A", "year": "1965"}').startswith("book.year"))
    check(problem('{"id": 1, "title": "A", "year": false}').startswith("book.year"))
    check(problem('{"id": 1, "title": "A", "year": 19.5}').startswith("book.year"))
    check(problem('{"id": 1, "title": "A", "tags": "sf"}').startswith("book.tags"))
    check(problem('{"id": 1, "title": "A", "tags": ["sf", 2]}').startswith("book.tags"))
    check(problem('{"id": 1, "title": "A", "tags": null}').startswith("book.tags"))
    check(problem('{"id": 1, "title": "A", "price": -1}').startswith("book.price"))
    check(problem('{"id": 1, "title": "A", "price": "9.5"}').startswith("book.price"))
    check(problem('{"id": 1, "title": "A", "price": true}').startswith("book.price"))

@test("canonical JSON")
def _():
    book = {"title": "Café", "id": 3, "tags": ["b", "a"], "year": None, "price": 2}
    check_eq(to_canonical_json(book), '{"id":3,"price":2,"tags":["b","a"],"title":"Café","year":null}')
    again = parse_book(to_canonical_json(parse_book('{"id": 3, "title": "Café"}')))
    check_eq(to_canonical_json(again), '{"id":3,"price":null,"tags":[],"title":"Café","year":null}')

